<template><div class="assistant-workspace"><aside class="assistant-sidebar"><span class="jade-eyebrow">陪你把生活安顿好</span><h2>租房的事，<br>问小易就好。</h2><button class="new-conversation" :disabled="loading" @click="newConversation">＋ 开始新的对话</button><p class="shortcut-heading">你可以从这里开始</p><button v-for="task in tasks" :key="task.key" class="task-shortcut" :disabled="loading" @click="chooseTask(task)"><span>{{ task.label }}</span><small>{{ task.note }}</small><b>↗</b></button><RouterLink class="my-messages-link" to="/app/messages">查看与房东的私信 →</RouterLink><div class="sidebar-life"><img src="/images/moving-day.png" alt="慢慢整理喜欢的生活" /><p>一个对话，把租房的小事理清楚。</p></div></aside><section class="assistant-main"><header class="assistant-heading"><div><span class="jade-eyebrow">找房 · 问政策 · 看合同 · 算费用</span><h1>小易</h1><p>说说眼前的问题，剩下的我们一起理清。</p></div><button class="stream-switch" role="switch" :aria-checked="streamMode" :disabled="loading" @click="streamMode=!streamMode; savePreference()"><span :class="{on:streamMode}"></span>逐字回复 {{ streamMode?'已开启':'已关闭' }}</button></header><div ref="messagesArea" class="assistant-transcript" aria-label="与小易的对话"><div v-if="!messages.length" class="assistant-welcome"><span>你好，我是小易。</span><h2>下一站生活，<br>我们从哪里聊起？</h2><p>告诉我想住哪里、预算多少，或上传喜欢的房间、待确认的合同。<br>不需要切换角色，我会根据你的需要查资料、找房和整理结果。</p><div class="welcome-prompts"><button v-for="task in tasks.slice(0,4)" :key="task.key" @click="chooseTask(task)">{{ task.label }} ↗</button></div></div><article v-for="(message,i) in messages" :key="message.id || i" class="assistant-message" :class="message.role"><span class="speaker-avatar">{{ message.role==='user'?'我':'易' }}</span><div class="assistant-message-body"><div v-if="message.attachment" class="uploaded-file"><img v-if="message.attachment.preview" :src="message.attachment.preview" alt="上传的参考图片" /><span>{{ message.attachment.name }}</span></div><div v-if="message.content" class="assistant-markdown" v-html="renderText(message)"></div><p v-if="message.streaming&&!message.content" class="assistant-progress" role="status">{{ message.progress || '小易正在整理…' }}<span></span></p><AssistantResults v-if="message.actions?.length" :actions="message.actions" @ask="setInput" /><AssistantDocumentCard v-for="file in filesFor(message)" :key="file.id || file.result.downloadUrl" :file="file.result" /><MessageDraftCard v-for="draft in message.privateDrafts||[]" :key="draft.id" :draft="draft" @cancel="id=>cancelDraft(message,id)" @sent="()=>draftSent(message,draft)" /><p v-if="message.error" class="assistant-error" role="alert">{{ message.error }}</p></div></article></div><div class="assistant-compose"><p v-if="error" class="assistant-error" role="alert">{{ error }}</p><div v-if="attachment" class="attachment-chip"><img v-if="attachment.preview" :src="attachment.preview" alt="待上传图片" /><span>{{ attachment.file.name }}<small>{{ attachment.purpose==='house'?'参考图片找房':'合同审查' }}</small></span><button :disabled="loading" aria-label="移除附件" @click="removeAttachment">×</button></div><div class="composer-box"><textarea ref="inputRef" v-model="inputText" rows="2" maxlength="12000" :disabled="loading" placeholder="问问小易，或上传图片和合同。Enter 发送，Shift+Enter 换行" aria-label="告诉小易你的需求" @keydown.enter.exact="enterSend" /><div class="composer-bottom"><div><button :disabled="loading" @click="pickFile('house')">＋ 房源图片</button><button :disabled="loading" title="支持图片、PDF、Word（DOCX），10MB以内" @click="pickFile('contract')">＋ 合同文件</button></div><button class="assistant-send" :disabled="loading || (!inputText.trim()&&!attachment)" @click="sendMessage">{{ loading?'小易处理中…':'发送 ↗' }}</button></div></div><input ref="houseFile" type="file" accept=".jpg,.jpeg,.png,.webp,.bmp" hidden @change="fileSelected($event,'house')" /><input ref="contractFile" type="file" accept=".jpg,.jpeg,.png,.webp,.bmp,.pdf,.docx" hidden @change="fileSelected($event,'contract')" /><p class="compose-note">需要发送私信或发布内容时仍会先确认；资料和建议请结合实际核实。</p></div></section></div></template>
<script setup>
import {requestId} from '../utils/requestId'
import {ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {useRoute} from 'vue-router'
import {useUserStore} from '../stores/user'
import request from '../api/index'
import AssistantResults from '../components/AssistantResults.vue'
import AssistantDocumentCard from '../components/AssistantDocumentCard.vue'
import MessageDraftCard from '../components/MessageDraftCard.vue'
import {messagesApi} from '../api/messages'
import {applyAssistantFrame,documentActions,visibleMessageText,renderAssistantMarkdown} from '../utils/assistantPresentation'
const route=useRoute(),user=useUserStore(),inputText=ref(''),messages=ref([]),loading=ref(false),streamMode=ref(localStorage.getItem('xiaoyi-stream')!=='off'),messagesArea=ref(null),inputRef=ref(null),houseFile=ref(null),contractFile=ref(null),attachment=ref(null),error=ref('')
const tasks=[{key:'find',label:'帮我找房',note:'预算、区域与通勤，一起考虑',prompt:'我想找房，请先帮我理清预算、城市和通勤需求。'},{key:'image',label:'用喜欢的图片找房',note:'上传一张喜欢的房间照片'},{key:'policy',label:'租房问题，有据可查',note:'押金、维修和权益，查完再说',prompt:'租房时押金退还和日常维修分别应怎样约定？请检索相关资料并给出来源。'},{key:'contract',label:'签字前，看看合同',note:'上传合同，或直接粘贴条款',prompt:'请帮我审查租房合同，我会上传文件或粘贴需要核对的条款。'},{key:'cost',label:'算算租房花费',note:'首月准备与每月支出',prompt:'请帮我估算租房的首次入住费用和每月支出，需要我提供哪些信息？'},{key:'document',label:'整理成一份文档',note:'对比报告、看房清单，都能带走',prompt:'请根据我们刚才讨论的内容生成一份PDF，方便我预览和保存。'}]
let activeRequest,alive=true;const objectUrls=new Set(),origin=window.location.origin
const cacheKey=()=>`xiaoyi-ui-${user.userId||'guest'}`
function save(){try{sessionStorage.setItem(cacheKey(),JSON.stringify(messages.value.slice(-40).map(m=>({...m,streaming:false,progress:'',attachment:m.attachment?{name:m.attachment.name}:null}))))}catch{}}
function savePreference(){localStorage.setItem('xiaoyi-stream',streamMode.value?'on':'off')}
async function scrollBottom(){await nextTick();if(messagesArea.value)messagesArea.value.scrollTop=messagesArea.value.scrollHeight}
function renderText(message){return renderAssistantMarkdown(message.role==='assistant'?visibleMessageText(message,origin):message.content,origin)}
function filesFor(message){return message.role==='assistant'?documentActions(message,origin):[]}
function setInput(text){inputText.value=text;inputRef.value?.focus()}
function chooseTask(task){if(task.key==='image'){pickFile('house');return}setInput(task.prompt||'')}
function pickFile(purpose){if(loading.value)return;(purpose==='house'?houseFile:contractFile).value?.click()}
function removeAttachment(){if(attachment.value?.preview){URL.revokeObjectURL(attachment.value.preview);objectUrls.delete(attachment.value.preview)}attachment.value=null}
function fileSelected(event,purpose){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>10*1024*1024){error.value='请选择10MB以内的文件';return}removeAttachment();const preview=/\.(png|jpe?g|webp|bmp)$/i.test(file.name)?URL.createObjectURL(file):'';if(preview)objectUrls.add(preview);attachment.value={file,purpose,preview};error.value='';inputRef.value?.focus()}
function enterSend(event){if(event.isComposing||event.keyCode===229)return;event.preventDefault();sendMessage()}
function draftSent(message,draft){draft.sent=true;save()}
function cancelDraft(message,id){message.privateDrafts=message.privateDrafts.filter(d=>d.id!==id);save()}
async function sendMessage(){
 if(loading.value||(!inputText.value.trim()&&!attachment.value))return
 const text=inputText.value.trim(),upload=attachment.value;inputText.value='';attachment.value=null;error.value='';loading.value=true;activeRequest=new AbortController()
 messages.value.push({id:requestId(),role:'user',content:text|| (upload?.purpose==='house'?'帮我找找类似的房间。':'请帮我审查这份合同。'),attachment:upload?{name:upload.file.name,preview:upload.preview}:null})
 const message={id:requestId(),role:'assistant',content:'',actions:[],privateDrafts:[],streaming:true,progress:upload?'正在处理上传的文件…':'小易正在理解你的需求…'};messages.value.push(message);const current=messages.value[messages.value.length-1];scrollBottom()
 try{
  if(upload){const form=new FormData();form.append('file',upload.file);form.append('purpose',upload.purpose);form.append('caption',text);const r=await request.post('/assistant/upload',form,{timeout:180000,signal:activeRequest.signal});Object.assign(current,{content:r.data.reply,actions:r.data.actions||[],privateDrafts:r.data.privateDrafts||[]})}
  else if(!streamMode.value){const r=await request.post('/assistant/reply',{message:text},{timeout:180000,signal:activeRequest.signal});Object.assign(current,{content:r.data.reply,actions:r.data.actions||[],privateDrafts:r.data.privateDrafts||[]})}
  else {
   const response=await fetch('/api/assistant/stream',{method:'POST',headers:{'Content-Type':'application/json','Accept':'text/event-stream'},body:JSON.stringify({message:text}),signal:activeRequest.signal})
   if(!response.ok)throw Error(`连接暂不可用（${response.status}），请稍后重试`)
   if(!response.headers.get('content-type')?.includes('text/event-stream')){const body=await response.json();throw Error(body.message||'回复服务暂不可用')}
   const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',ended=false
   while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});buffer=buffer.replace(/\r\n/g,'\n');const frames=buffer.split('\n\n');buffer=frames.pop();for(const frame of frames){applyAssistantFrame(current,frame);if(frame.includes('event:done')||frame.includes('event: done'))ended=true}if(!current.actions.length)scrollBottom()}
   buffer+=decoder.decode();if(buffer.trim()){applyAssistantFrame(current,buffer);if(buffer.includes('event:done')||buffer.includes('event: done'))ended=true}
   if(!ended&&!current.error)current.error='连接已中断，以上内容可能不完整，可以重新提问。'
  }
 }catch(e){if(alive)current.error=e.name==='AbortError'?'本次回复已停止':e.message||'暂时无法完成，请稍后重试'}
 finally{current.streaming=false;current.progress='';loading.value=false;save();scrollBottom()}
}
async function newConversation(){if(loading.value)return;try{await request.delete('/assistant/memory');messages.value=[];error.value='';save();inputText.value='';removeAttachment();for(const url of objectUrls)URL.revokeObjectURL(url);objectUrls.clear();inputRef.value?.focus()}catch(e){error.value=e.message||'暂时无法开始新对话，请稍后重试'}}
function taskFromRoute(){const task=tasks.find(t=>t.key===route.query.task);if(task&&task.key!=='image')setInput(task.prompt||'');else if(task?.key==='image')setInput('请点击下方“房源图片”上传参考照片，我来帮你找相似房源。')}
watch(()=>route.query.task,taskFromRoute)
onMounted(async()=>{try{const cached=JSON.parse(sessionStorage.getItem(cacheKey())||'[]');messages.value=Array.isArray(cached)?cached:[]}catch{}taskFromRoute();inputRef.value?.focus();scrollBottom();try{if(user.isLogin){const r=await messagesApi.pending();const known=new Set(messages.value.flatMap(m=>(m.privateDrafts||[]).map(d=>d.id)));const pending=(r.data||[]).filter(d=>!known.has(d.id));if(alive&&pending.length)messages.value.push({id:requestId(),role:'assistant',content:'这些私信还没有发送，你可以确认、编辑或取消。',actions:[],privateDrafts:pending})}}catch{}})
onBeforeUnmount(()=>{alive=false;activeRequest?.abort();for(const url of objectUrls)URL.revokeObjectURL(url)})
</script>
<style scoped>
.assistant-workspace{display:grid;grid-template-columns:255px minmax(0,1fr);height:calc(100svh - var(--header-height));background:#fffefa;color:var(--jade-ink);max-width:1800px;margin:auto}.assistant-sidebar{padding:30px 22px;background:#eff2e9;border-right:1px solid var(--jade-line);overflow:auto;display:flex;flex-direction:column}.assistant-sidebar>h2{font-family:var(--font-display);font-size:27px;font-weight:500;line-height:1.7;margin:17px 0 24px}.new-conversation{padding:13px;border:0;border-radius:4px;background:var(--jade-600);color:white;font:inherit;font-size:12px;cursor:pointer}.shortcut-heading{font-size:10px;color:var(--jade-muted);margin:27px 0 12px}.task-shortcut{position:relative;padding:12px 10px;text-align:left;border:0;border-radius:4px;background:none;color:var(--jade-900);cursor:pointer}.task-shortcut:hover{background:#e3ebdc}.task-shortcut>span{font-size:12px;display:block}.task-shortcut>small{display:block;font-size:9px;color:var(--jade-muted);margin-top:6px;line-height:1.7}.task-shortcut b{position:absolute;right:8px;top:12px;font-size:12px;font-weight:400}.my-messages-link{font-size:11px;color:var(--jade-700);border-top:1px solid var(--jade-line);padding-top:18px;margin:20px 0}.sidebar-life{margin-top:auto;padding-top:25px}.sidebar-life img{width:100%;height:135px;object-fit:cover;border-radius:4px}.sidebar-life p{font-size:10px;color:var(--jade-muted);line-height:1.8;margin:10px 0 0}.assistant-main{display:flex;min-width:0;flex-direction:column;min-height:0}.assistant-heading{padding:25px 30px 20px;border-bottom:1px solid var(--jade-line);display:flex;justify-content:space-between;align-items:center;gap:20px}.assistant-heading h1{font-family:var(--font-display);font-size:33px;font-weight:500;line-height:1.4;margin:9px 0 5px}.assistant-heading p{font-size:11px;color:var(--jade-muted);margin:0}.stream-switch{border:1px solid var(--jade-line);background:#f7f9f2;border-radius:20px;padding:9px 13px;display:flex;align-items:center;gap:8px;font-size:11px;color:var(--jade-muted);white-space:nowrap;cursor:pointer}.stream-switch>span{width:22px;height:12px;border-radius:8px;background:#d7dfd1;position:relative}.stream-switch>span::after{content:'';position:absolute;width:8px;height:8px;background:white;border-radius:50%;left:2px;top:2px;transition:transform .2s}.stream-switch>span.on{background:var(--jade-600)}.stream-switch>span.on::after{transform:translateX(10px)}.assistant-transcript{flex:1;overflow:auto;padding:30px clamp(20px,4vw,65px);min-height:0;scroll-behavior:smooth}.assistant-message{display:flex;gap:13px;margin-bottom:32px;align-items:flex-start}.assistant-message.user{flex-direction:row-reverse}.speaker-avatar{display:grid;place-items:center;width:31px;height:31px;flex-shrink:0;border-radius:10px;background:#e6eee0;color:var(--jade-700);font-family:var(--font-display);font-size:15px}.user>.speaker-avatar{background:var(--jade-600);color:white;border-radius:50%}.assistant-message-body{min-width:0;max-width:calc(100% - 44px);width:100%}.user>.assistant-message-body{width:auto;max-width:78%;padding:12px 17px;background:#e6efdf;border-radius:12px 0 12px 12px}.assistant-markdown{font-size:14px;line-height:1.95;overflow-wrap:anywhere}.assistant-markdown :deep(p){margin:0 0 14px}.assistant-markdown :deep(p:last-child){margin-bottom:0}.assistant-markdown :deep(h1),.assistant-markdown :deep(h2),.assistant-markdown :deep(h3){line-height:1.6;margin:22px 0 12px;font-size:18px}.assistant-markdown :deep(h4){font-size:15px;margin:15px 0 9px}.assistant-markdown :deep(ul),.assistant-markdown :deep(ol){padding-left:22px;margin:12px 0}.assistant-markdown :deep(blockquote){padding:10px 16px;border-left:3px solid #92b59e;background:#f1f5ed;margin:15px 0;color:#607560}.assistant-markdown :deep(pre){padding:15px;background:#f1f4eb;border-radius:5px;overflow:auto;font-size:12px;white-space:pre-wrap}.assistant-markdown :deep(code){font-size:12px;background:#eff3e9;padding:2px 4px;border-radius:3px}.assistant-markdown :deep(table){border-collapse:collapse;font-size:12px;display:block;overflow:auto;max-width:100%;margin:15px 0}.assistant-markdown :deep(th),.assistant-markdown :deep(td){border:1px solid var(--jade-line);padding:8px 12px}.assistant-markdown :deep(th){background:#eff3e9}.assistant-markdown :deep(a){color:var(--jade-600);text-decoration:underline}.assistant-markdown :deep(hr){border:0;border-top:1px solid var(--jade-line);margin:20px 0}.assistant-progress{font-size:12px;color:var(--jade-muted);line-height:1.8;margin:3px 0 12px}.assistant-progress>span{display:inline-block;margin-left:7px;width:5px;height:5px;border-radius:50%;background:var(--jade-600);animation:pulse 1s infinite}.assistant-error{font-size:12px;color:#a65342;line-height:1.8;margin:10px 0}.assistant-welcome{max-width:750px;margin:20px auto 30px;padding:15px}.assistant-welcome>span{font-size:13px;color:var(--jade-700)}.assistant-welcome h2{font-family:var(--font-display);font-size:clamp(30px,3.2vw,44px);font-weight:500;line-height:1.6;margin:15px 0 20px}.assistant-welcome>p{font-size:13px;line-height:2;color:var(--jade-muted)}.welcome-prompts{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:28px}.welcome-prompts button{padding:15px 18px;background:#f2f5eb;border:1px solid var(--jade-line);text-align:left;border-radius:5px;font-size:12px;color:var(--jade-900);cursor:pointer}.assistant-compose{border-top:1px solid var(--jade-line);padding:15px 30px 10px;background:#fffefa}.composer-box{border:1px solid var(--jade-line);border-radius:8px;background:#f9faf5;padding:12px 15px}.composer-box:focus-within{border-color:#97bba5;box-shadow:0 0 0 3px #168b7808}.composer-box textarea{width:100%;border:0;outline:none;resize:vertical;min-height:45px;max-height:180px;background:none;color:var(--jade-ink);font:inherit;font-size:13px;line-height:1.8}.composer-box textarea::placeholder{color:#9da696;font-size:12px}.composer-bottom{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:10px}.composer-bottom>div{display:flex;gap:15px}.composer-bottom>div>button{border:0;background:none;color:var(--jade-muted);padding:4px 0;font-size:11px;cursor:pointer}.composer-bottom>.assistant-send{background:var(--jade-600);color:white;border:0;border-radius:5px;padding:9px 18px;font-size:12px;cursor:pointer}.compose-note{font-size:9px;color:#9aa492;line-height:1.7;margin:7px 0 0;text-align:center}.attachment-chip{display:flex;gap:10px;align-items:center;margin-bottom:12px;padding:9px 12px;background:#f0f4e9;border-radius:5px;width:fit-content;max-width:100%;font-size:11px}.attachment-chip>img{width:42px;height:42px;object-fit:cover;border-radius:4px}.attachment-chip>span{overflow-wrap:anywhere}.attachment-chip small{display:block;font-size:9px;color:var(--jade-muted);margin-top:4px}.attachment-chip>button{border:0;background:none;font-size:20px;color:var(--jade-muted);cursor:pointer}.uploaded-file{display:flex;flex-direction:column;gap:7px;font-size:11px}.uploaded-file img{max-width:240px;max-height:170px;object-fit:contain;border-radius:4px}.uploaded-file+div{margin-top:9px}.assistant-message-body :deep(.draft-card){margin-top:15px}.assistant-send:disabled,button:disabled{opacity:.45;cursor:default}@keyframes pulse{50%{opacity:.3}}@media(max-width:1050px){.assistant-workspace{grid-template-columns:210px 1fr}.assistant-sidebar{padding:25px 17px}.assistant-heading{padding:22px}.assistant-transcript{padding:25px 22px}.assistant-compose{padding:12px 20px 9px}}@media(max-width:750px){.assistant-workspace{grid-template-columns:1fr}.assistant-sidebar{display:none}.assistant-heading{padding:16px 20px}.assistant-heading h1{font-size:27px}.assistant-heading p{display:none}.assistant-heading .jade-eyebrow{font-size:9px}.assistant-transcript{padding:24px 15px}.assistant-message{gap:8px}.speaker-avatar{width:27px;height:27px;font-size:13px}.assistant-message-body{max-width:calc(100% - 35px)}.assistant-compose{padding:12px 13px 8px}.stream-switch{padding:8px 10px;font-size:10px}.assistant-markdown{font-size:13px}.welcome-prompts{grid-template-columns:1fr}.composer-bottom>div{gap:12px}.compose-note{font-size:8px}}@media(prefers-reduced-motion:reduce){.assistant-transcript{scroll-behavior:auto}.assistant-progress>span{animation:none}.stream-switch>span::after{transition:none}}
</style>
